```typescript
import React, { useEffect, useState } from 'react';
import { FormControl, FormHelperText, Input, MenuItem, Select, SelectChangeEvent } from '@material-ui/core';
import { useField } from 'formik';

interface IInputProps {
  name: string;
  label?: string;
  value?: any;
  placeholder?: string;
  onChange?: any;
  error?: string;
  helperText?: string;
  isPassword?: boolean;
  isSearch?: boolean;
  options?: any[];
}

const Input: React.FC<IInputProps> = ({ name, label, value, placeholder, onChange, error, helperText, isPassword, isSearch, options }) => {
  const [field, meta] = useField({ name, type: isPassword ? 'password' : 'text', placeholder: isSearch ? 'Search...' : placeholder, helperText: helperText ?? '', error: meta.touched && meta.error, value: value ?? '', onChange: onChange ?? undefined });

  return (
    <FormControl error={!!meta.error}>
      {!!label && <InputLabel>{label}</InputLabel>}
      <Input
        {...field}
        onChange={(e) => {
          const { name, value } = e.target;
          field.onChange({ name, value, ...(field.value ?? {}) }));
        />
      {meta.touched && meta.error && (
        <FormHelperText>{meta.error}</FormHelperText>
      )}
    </FormControl>
  );
};

export default Input;
```

